import React, { Suspense, lazy } from 'react';
import ReactDOM from 'react-dom/client';
import { FILES } from './data';

// Each page loads only its own fonts and global styles: the professional homepage
// at the root, and the 16-bit file manager at /retro/.
const Home = lazy(() => import('./Home'));
const Retro = lazy(() => import('./App'));

const isRetro = /^\/retro(\/|$)/.test(window.location.pathname);

// Links shared before the move pointed at the root with a file hash, such as /#carspy.
const hash = window.location.hash.slice(1).toLowerCase();
if (!isRetro && (hash === 'about' || FILES.some((f) => f.id === hash))) {
  window.location.replace(`/retro/#${hash}`);
}

const root = ReactDOM.createRoot(document.getElementById('root') as HTMLElement);
root.render(
  <React.StrictMode>
    <Suspense fallback={null}>{isRetro ? <Retro /> : <Home />}</Suspense>
  </React.StrictMode>
);
